// Like button functionality
// Clicking "Like" toggles the liked state: icon + text turn blue and a
// like count of 1 appears next to it. Clicking again removes the like.
function toggleLike(btn) {
  const icon = btn.querySelector('i');
  const countEl = btn.querySelector('.like-count');
  const isLiked = btn.classList.toggle('liked');

  if (isLiked) {
    icon.classList.remove('fa-regular');
    icon.classList.add('fa-solid');
    countEl.textContent = '1';
  } else {
    icon.classList.remove('fa-solid');
    icon.classList.add('fa-regular');
    countEl.textContent = '';
  }
}

// Mobile left-sidebar drawer (Friends, Groups, Pages, etc.)
function toggleSidebar() {
  document.querySelector('.sidebar-left').classList.toggle('open');
  document.getElementById('sidebarOverlay').classList.toggle('active');
}

function closeSidebar() {
  document.querySelector('.sidebar-left').classList.remove('open');
  document.getElementById('sidebarOverlay').classList.remove('active');
}

// Shared profile photo (embedded once here, applied to every avatar
// marked with data-photo="me" in index.html) to keep the HTML file small.
const PROFILE_PHOTO = "data:image/jpeg;base64,";

document.addEventListener("DOMContentLoaded", function () {
  document.querySelectorAll("img[data-photo='me']").forEach(function (img) {
    img.src = PROFILE_PHOTO;
  });
});
